$sp = New-Object System.IO.Ports.SerialPort $Port,115200,None,8,One
$sp.ReadTimeout = 500
$sp.DtrEnable = $false
$sp.RtsEnable = $false
$sp.Open()
Start-Sleep -Milliseconds 300
try { while ($true) { $null = $sp.ReadExisting(); Start-Sleep -Milliseconds 100 } } catch {}
$sp.DiscardInBuffer()

function Send-Cmd($s) {
    Write-Output ("<<<SEND>>> " + $s)
    $sp.Write($s + "`r`n")
}

function Drain($ms) {
    $end = (Get-Date).AddMilliseconds($ms)
    while ((Get-Date) -lt $end) {
        try {
            $line = $sp.ReadExisting()
            if ($line) { Write-Output ($line -replace "`r","") }
        } catch {}
        Start-Sleep -Milliseconds 120
    }
}

