import re
MAP="/home/flash/vela-p4/nuttx/nuttx.map"
syms=[]
lines=open(MAP,errors="ignore").read().splitlines()
for i,l in enumerate(lines):
    m=re.match(r"\s*(0x[0-9a-fA-F]{8})\s+(0x[0-9a-fA-F]+)\s+(\S+)",l)
    if m:
        addr=int(m.group(1),16); size=int(m.group(2),16); src=m.group(3)
        # next non-empty trimmed line that is a bare symbol name
        j=i+1
        while j<len(lines) and not lines[j].strip(): j+=1
        if j<len(lines):
            t=lines[j].strip()
            if re.fullmatch(r"[A-Za-z_.$][A-Za-z0-9_.$]*",t):
                syms.append((addr,size,t,src))
syms.sort()
import bisect
addrs=[s[0] for s in syms]
def lookup(a):
    k=bisect.bisect_right(addrs,a)-1
    if k<0: return None
    addr,size,t,src=syms[k]
    if a<addr+size or size==0:
        off=a-addr
        return f"{t}+0x{off:x} ({src})"
    return None
