    # include wqueue
    src = src.replace("#include <poll.h>", "#include <poll.h>\n#include <nuttx/wqueue.h>", 1)

    # worker + storage after isr handler function end
    anchor = """  poll_notify(priv->fds, CONFIG_INPUT_GT9XX_NPOLLWAITERS, POLLIN);
  return OK;
}"""
    assert src.count(anchor) == 1
    worker = anchor + """

/****************************************************************************
 * Name: gt9xx_poll_worker (optional polling mode)
 *
 * For panels whose INT line is not wired (e.g. Function-EV-Board LCD
 * adapter).  Periodically fakes the ISR so that read()/poll() see events.
 ****************************************************************************/

#ifdef CONFIG_INPUT_GT9XX_POLL
static struct work_s g_gt9xx_poll_work;

static void gt9xx_poll_worker(FAR void *arg)
{
  FAR struct gt9xx_dev_s *priv = (FAR struct gt9xx_dev_s *)arg;
  irqstate_t flags;

  flags = enter_critical_section();
  priv->int_pending = true;
  leave_critical_section(flags);

  poll_notify(priv->fds, CONFIG_INPUT_GT9XX_NPOLLWAITERS, POLLIN);

  work_queue(LPWORK, &g_gt9xx_poll_work, gt9xx_poll_worker, arg,
             MSEC2TICK(CONFIG_INPUT_GT9XX_POLL));
}
#endif"""
    src = src.replace(anchor, worker)

    # schedule at end of gt9xx_register (before final return)
    reg_anchor = """  DEBUGASSERT(priv->board->irq_enable);"""
