nrep = len(pat.findall(s))
assert nrep == 1, f"setup matches={nrep}"
s = pat.sub(loop, s)

# neutralize restart body
rs = re.search(r"(static void IRAM_ATTR esp_mipi_dsi_dma_restart\([^\)]*\)[\s\S]*?\n\{\n)([\s\S]*?)(\n\})", s)
