constblk = """      const uint32_t chunk_items = 4095u;   /* DW-GDMA block_ts max(12bit) */
      const size_t   chunk_bytes = (size_t)chunk_items * 8u;
      const uint32_t n_llis      =
        (uint32_t)((fb_size + chunk_bytes - 1) / chunk_bytes);

"""
